'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const root='releases/v407',base='releases/v404',read=(dir,name)=>fs.readFileSync(dir+'/'+name,'utf8'),hash=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const manifest=JSON.parse(read(root,'manifest.json')),provenance=JSON.parse(read(root,'provenance.json'));
assert.equal(manifest.release,'v407');assert.equal(manifest.base_release,'v404');assert.equal(manifest.entry,'app.html');
assert.deepEqual([...Object.keys(manifest.files),'manifest.json'].sort(),fs.readdirSync(root).sort(),'every release asset is hashed');
assert.deepEqual(Object.keys(provenance.protected_base_files).sort(),fs.readdirSync(base).sort(),'every prior asset is protected');
for(const[name,expected]of Object.entries(manifest.files))assert.equal(hash(root+'/'+name),expected,'release '+name);
for(const[name,expected]of Object.entries(provenance.protected_base_files))assert.equal(hash(base+'/'+name),expected,'immutable base '+name);
assert.equal(manifest.protected_manifest.path,base+'/manifest.json');assert.equal(hash(manifest.protected_manifest.path),manifest.protected_manifest.sha256);
const additions=['lts-v407-wealth-summary.js','lts-v407-document-review.js','lts-v408-cipo-source.js'];
assert.deepEqual(fs.readdirSync(root).sort(),[...fs.readdirSync(base),...additions].sort(),'only reviewed modules are added');
for(const name of fs.readdirSync(base))if(!['app.html','manifest.json','provenance.json'].includes(name))assert.equal(hash(root+'/'+name),hash(base+'/'+name),'existing runtime remains identical '+name);
let expected=read(base,'app.html').replaceAll('V404','V407').replace('v404-fgts-documentary-20261104','v407-wealth-documents-20261104');
for(const name of additions)expected=expected.replace('</body>','<script src="'+name+'"></script>\n</body>');
assert.equal(read(root,'app.html'),expected,'only release identity and additive scripts change');
assert.deepEqual(JSON.parse(read('mobile','current.json')),{release:'v407',entry:'../releases/v407/app.html'});
assert.equal(hash(root+'/lts-v407-document-review.js'),hash('lts-v407-document-review.js'),'reviewed document source is the released source');
for(const key of ['candidate_only','financial_event_writers_added','received_financial_payloads_modified','private_http_validated','physical_mobile_validated'])assert.equal(provenance[key],false,key);
assert.equal(provenance.document_uploads_use_existing_authenticated_storage_and_inbox,true);
assert.equal(provenance.partial_net_requires_reconciled_dated_debt_components,true);
console.log(JSON.stringify({pass:true,release:'v407',assets:fs.readdirSync(root).length,immutable_v404:true,stable_mobile_entry:true,financial_event_writers_added:false}));
